import { Component, inject, signal } from '@angular/core';
import { CourseApi, CourseDto } from './course-api';

@Component({ selector: 'app-courses-page', templateUrl: './courses-page.html' })
export class CoursesPage {
  private readonly api = inject(CourseApi);
  protected readonly courses = signal<CourseDto[]>([]);

  constructor() {
    this.api.list().subscribe(list => this.courses.set(list));
  }

  protected add(title: string, hours: number): void {
    this.api.create({ title, hours }).subscribe(created =>
      this.courses.update(list => [...list, created]));
  }

  protected rename(course: CourseDto, title: string): void {
    this.api.update(course.id, { title, hours: course.hours }).subscribe(() =>
      this.courses.update(list => list.map(c => c.id === course.id ? { ...c, title } : c)));
  }
}

protected toggleDone(topic: Topic): void {
  const before = this.topics();
  this.topics.update(list => list.map(t => t.id === topic.id ? { ...t, done: !t.done } : t));

  this.api.setDone(topic.id, !topic.done).subscribe({
    error: () => {
      this.topics.set(before);
      this.toast.show('Could not save. Your change was undone.');
    },
  });
}

