import { HttpErrorResponse } from '@angular/common/http';
import { FormGroup } from '@angular/forms';

export function applyServerErrors(form: FormGroup, err: HttpErrorResponse): boolean {
  const errors = err.status === 400 ? err.error?.errors as Record<string, string[]> | undefined : undefined;
  if (!errors) return false;

  for (const [field, messages] of Object.entries(errors)) {
    const name = Object.keys(form.controls).find(k => k.toLowerCase() === field.toLowerCase());
    if (name) form.controls[name].setErrors({ server: messages[0] });
  }
  form.markAllAsTouched();
  return true;
}

