import { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { catchError, throwError } from 'rxjs';
import { Toast } from './toast';

export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const toast = inject(Toast);
  return next(req).pipe(
    catchError((err: HttpErrorResponse) => {
      if (err.status === 0) toast.show('You seem to be offline. Check your connection.');
      else if (err.status >= 500) toast.show('Something went wrong on our side. Please try again.');
      return throwError(() => err);
    }),
  );
};

export function messageFor(status: number, traceId?: string): string {
  const ref = traceId ? ` (reference: ${traceId})` : '';
  switch (status) {
    case 0:   return 'No connection. Check your internet and try again.';
    case 403: return 'You do not have permission to do this.';
    case 404: return 'This item no longer exists. It may have been deleted.';
    case 409: return 'Someone else changed this. Reload to see the latest version.';
    default:  return status >= 500 ? `Something went wrong on our side${ref}.` : 'Please check your input.';
  }
}

import { Component, input, signal, effect } from '@angular/core';

@Component({
  selector: 'app-delayed-spinner',
  template: `@if (visible()) { <span class="spinner" role="status">Loading...</span> }`,
})
export class DelayedSpinner {
  readonly loading = input.required<boolean>();
  protected readonly visible = signal(false);

  constructor() {
    effect(onCleanup => {
      if (!this.loading()) { this.visible.set(false); return; }
      const timer = setTimeout(() => this.visible.set(true), 300);
      onCleanup(() => clearTimeout(timer));
    });
  }
}

