app.MapGet("/api/students", async (CollegeContext db, int page = 1, int pageSize = 20) =>
{
    pageSize = Math.Clamp(pageSize, 1, 100);
    page = Math.Max(page, 1);

    var query = db.Students.OrderBy(s => s.Name).ThenBy(s => s.Id);
    var total = await query.CountAsync();
    var items = await query.Skip((page - 1) * pageSize).Take(pageSize)
        .Select(s => new StudentRow(s.Id, s.Name))
        .ToListAsync();

    return new Page<StudentRow>(items, total, page, pageSize);
});

import { Component, computed, input, output } from '@angular/core';

@Component({
  selector: 'app-pager',
  template: `
    <nav aria-label="Pages">
      <button type="button" [disabled]="page() <= 1" (click)="go.emit(page() - 1)">Previous</button>
      <span aria-current="page">Page {{ page() }} of {{ pages() }}</span>
      <button type="button" [disabled]="page() >= pages()" (click)="go.emit(page() + 1)">Next</button>
    </nav>
  `,
})
export class Pager {
  readonly page = input.required<number>();
  readonly total = input.required<number>();
  readonly pageSize = input(20);
  readonly go = output<number>();

  protected readonly pages = computed(() => Math.max(1, Math.ceil(this.total() / this.pageSize())));
}

import { Component, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';

interface Activity { id: number; text: string; }
interface Slice { items: Activity[]; next: number | null; }

@Component({
  selector: 'app-activity-feed',
  template: `
    @for (a of items(); track a.id) { <p>{{ a.text }}</p> }
    @if (next() !== null) { <button type="button" (click)="more()">Load more</button> }
  `,
})
export class ActivityFeed {
  private readonly http = inject(HttpClient);
  protected readonly items = signal<Activity[]>([]);
  protected readonly next = signal<number | null>(0);

  constructor() { this.more(); }

  protected more(): void {
    const after = this.next();
    const params: Record<string, number> = after ? { after } : {};
    this.http.get<Slice>('/api/activity', { params }).subscribe(slice => {
      this.items.update(list => [...list, ...slice.items]);
      this.next.set(slice.next);
    });
  }
}

app.MapGet("/api/students", async (CollegeContext db, string? q, string? city, int? year) =>
{
    IQueryable<Student> query = db.Students;

    if (!string.IsNullOrWhiteSpace(q))
        query = query.Where(s => s.Name.Contains(q.Trim()));
    if (!string.IsNullOrWhiteSpace(city))
        query = query.Where(s => s.City == city);
    if (year is not null)
        query = query.Where(s => s.Year == year);

    return await query.OrderBy(s => s.Name).Take(50)
        .Select(s => new StudentRow(s.Id, s.Name)).ToListAsync();
});

import { Component, signal } from '@angular/core';
