@Component({ selector: 'app-student-search', templateUrl: './student-search.html' })
export class StudentSearch {
  protected readonly filters = signal<Filters>({ q: '', city: '', year: null });

  protected readonly results = httpResource<StudentRow[]>(() => {
    const f = this.filters();
    const params: Record<string, string | number> = {};
    if (f.q.trim()) params['q'] = f.q.trim();
    if (f.city) params['city'] = f.city;
    if (f.year !== null) params['year'] = f.year;
    return { url: '/api/students', params };
  });
}

