import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

export interface Me { id: number; name: string; roles: string[]; }

@Injectable({ providedIn: 'root' })
export class Auth {
  private readonly http = inject(HttpClient);
  readonly user = signal<Me | null>(null);

  load(): Observable<Me> {
    return this.http.get<Me>('/api/auth/me').pipe(tap(me => this.user.set(me)));
  }

  signIn(email: string, password: string): Observable<Me> {
    return this.http.post<Me>('/api/auth/sign-in', { email, password }).pipe(tap(me => this.user.set(me)));
  }

  signOut(): Observable<void> {
    return this.http.post<void>('/api/auth/sign-out', {}).pipe(tap(() => this.user.set(null)));
  }
}

public record CourseDto(int Id, string Title, int Hours, byte[] Version);
public record CourseUpdate(string Title, int Hours, byte[] Version);

app.MapPut("/api/courses/{id:int}", async (int id, CourseUpdate input, CollegeContext db) =>
{
    var course = await db.Courses.FindAsync(id);
    if (course is null) return Results.NotFound();

    db.Entry(course).Property(c => c.RowVersion).OriginalValue = input.Version;
    course.Title = input.Title;
    course.Hours = input.Hours;

    try { await db.SaveChangesAsync(); }
    catch (DbUpdateConcurrencyException) { return Results.Conflict(); }

    return Results.Ok(new CourseDto(course.Id, course.Title, course.Hours, course.RowVersion));
});

protected save(): void {
  const course = this.course();
  this.api.update(course.id, { ...this.form.getRawValue(), version: course.version }).subscribe({
    next: saved => this.course.set(saved),          // keeps the new version
    error: (err: HttpErrorResponse) => {
      if (err.status === 409) {
        this.conflict.set(true);   // shows: "Someone else changed this course. Reload to see their version."
      }
    },
  });
}

protected reload(): void {
  this.api.get(this.course().id).subscribe(latest => {
    this.course.set(latest);
    this.form.reset({ title: latest.title, hours: latest.hours });
    this.conflict.set(false);
  });
}
